using System.Net;
using Microsoft.EntityFrameworkCore;
using PersonalFinance.Api.Application;
using Xunit;
namespace PersonalFinance.Tests;
public partial class ConcertTests {
 [ProfileSqlFact] public async Task P1SharedSourceReservationsCurrenciesAndInstallmentsStayExplicit() {
  await using var f=await LifecycleFixture.Create();var pay=await f.Tx("Expense","100");var cost=new ConcertCost(Guid.NewGuid().ToString(),"Hotel",pay,null,"60","本人","本人");var saved=await Data(await Write(f.Client,"/concerts",Scene() with{Costs=[cost]}));var sid=saved.GetProperty("id").GetString()!;
  var trip=new ConcertTrip("共享测试","CNY","200","Planning",[],[],[new(Guid.NewGuid().ToString(),pay,"100",[])],"");Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Write(f.Client,"/concerts/trips",trip)).StatusCode);
  trip=trip with{SceneIds=[sid],Expenses=[new(Guid.NewGuid().ToString(),pay,"100",[new(sid,cost.Id)])]};await Data(await Write(f.Client,"/concerts/trips",trip));
  var usd=await Data(await Write(f.Client,"/accounts",new{name="隔离美元",type="Cash",currency="USD",openingBalance="1000"}));var foreign=await Data(await Write(f.Client,"/transactions/expense",new PersonalFinance.Api.Contracts.SaveTransaction("Expense","20",usd.GetProperty("id").GetString()!,new(2026,1,1,10,0,0,TimeSpan.Zero),CategoryId:f.Expense.Id)));var fxTrip=trip with{Name="原币旅行",SceneIds=[],Expenses=[new(Guid.NewGuid().ToString(),foreign.GetProperty("id").GetString()!,"20",[],"USD")]};var fxSaved=await Data(await Write(f.Client,"/concerts/trips",fxTrip));
  await Data(await Write(f.Client,"/concerts/planning-budgets",new ConcertPlanBudget("美元旅行预算",2026,"USD","Trip",fxSaved.GetProperty("id").GetString(),"30",null,null,"0","")));var budgets=await Data(await f.Client.GetAsync("/api/concerts/planning-budgets"));Assert.Equal("20.00",budgets[0].GetProperty("report").GetProperty("actual").GetString());
  await Data(await Write(f.Client,"/concerts/planning-budgets",new ConcertPlanBudget("单场预算",2026,"CNY","Scene",sid,"80",null,null,"0","")));var sceneBudgets=await Data(await f.Client.GetAsync("/api/concerts/planning-budgets"));Assert.Equal("60.00",sceneBudgets.EnumerateArray().Single(b=>b.GetProperty("input").GetProperty("scope").GetString()=="Scene").GetProperty("report").GetProperty("actual").GetString());
  var income=await f.Tx("Income","30");var second=await f.Tx("Income","20");var back=await f.Tx("Expense","10");var c=new ConcertCollection("分次出售","CNY","商品","","","","","","Sold",null,null,null,"0",income,back,[],"",AdditionalSaleIds:[second]);var collection=await Data(await Write(f.Client,"/concerts/collections",c));var id=collection.GetProperty("id").GetString()!;var version=collection.GetProperty("version").GetString()!;
  var list=await Data(await f.Client.GetAsync("/api/concerts/collections"));Assert.Equal("40.00",list[0].GetProperty("report").GetProperty("netSale").GetString());Assert.Equal(System.Text.Json.JsonValueKind.Null,list[0].GetProperty("report").GetProperty("cost").ValueKind);
  Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Write(f.Client,"/concerts/collections/"+id,c with{State="Gifted"},version,put:true)).StatusCode);Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Write(f.Client,"/concerts/collections/"+id,c with{AdditionalSaleIds=[income]},version,put:true)).StatusCode);
  Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Write(f.Client,"/concerts/trips",trip with{SceneIds=[],Expenses=[new(Guid.NewGuid().ToString(),back,"10",[])]})).StatusCode);var separateIncome=await f.Tx("Income","100");Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Write(f.Client,"/concerts/collections",c with{SaleTransactionId=separateIncome,AdditionalSaleIds=[],ReturnTransactionId=pay})).StatusCode);
  // Legacy payloads without the optional installment arrays preserve earlier real receipts.
  await Data(await Write(f.Client,"/concerts/collections/"+id,c with{AdditionalSaleIds=null,Note="仅补说明"},version,put:true));list=await Data(await f.Client.GetAsync("/api/concerts/collections"));Assert.Equal("40.00",list[0].GetProperty("report").GetProperty("netSale").GetString());
  f.Db.ChangeTracker.Clear();var original=await f.Db.Transactions.SingleAsync(t=>t.Id==pay);original.Status="NeedsReview";await f.Db.SaveChangesAsync();var trips=await Data(await f.Client.GetAsync("/api/concerts/trips"));Assert.Contains(trips.EnumerateArray(),t=>t.GetProperty("report").GetProperty("warnings").GetArrayLength()>0);
 }
 [ProfileSqlFact] public async Task TripsExperiencesAndMemoriesKeepOwnerBoundariesAndNeverDuplicateLedger() {
  await using var f=await LifecycleFixture.Create();var tx=await f.Tx("Expense","100");var cost=new ConcertCost(Guid.NewGuid().ToString(),"Hotel",tx,null,"60","本人","本人");var scene=await Data(await Write(f.Client,"/concerts",Scene() with{Costs=[cost]}));var sid=scene.GetProperty("id").GetString()!;var count=await f.Db.Transactions.CountAsync();
  var trip=new ConcertTrip("联合旅行","CNY","200","Booked",[sid],[new(Guid.NewGuid().ToString(),"Hotel","预订酒店",DateTimeOffset.UtcNow,DateTimeOffset.UtcNow.AddDays(1),"Asia/Shanghai","Booked","TEST-ORDER","")],[new(Guid.NewGuid().ToString(),tx,"100",[new(sid,cost.Id)])],"");
  var saved=await Data(await Write(f.Client,"/concerts/trips",trip));var id=saved.GetProperty("id").GetString()!;var version=saved.GetProperty("version").GetString()!;var list=await Data(await f.Client.GetAsync("/api/concerts/trips"));var report=list.EnumerateArray().Single(x=>x.GetProperty("id").GetString()==id).GetProperty("report");Assert.Equal("40.00",report.GetProperty("unassigned").GetString());
  Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Write(f.Client,"/concerts/trips",trip)).StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await Write(f.Client,"/concerts/trips/"+id,trip,"0",put:true)).StatusCode);
  var venue=await Data(await Write(f.Client,"/concerts/experiences/venues",new ConcertVenue("场馆","上海","地址","地铁","")));var vid=venue.GetProperty("id").GetString()!;
  var seat=new ConcertSeatExperience(sid,vid,"A","1排1座",4,4,3,4,"轻微遮挡",[],"");await Data(await Write(f.Client,"/concerts/experiences/seats",seat));Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Write(f.Client,"/concerts/experiences/seats",seat with{View=6})).StatusCode);
  var memory=new ConcertMemory(sid,"日记","观演记录","朋友",4,[new("安可曲","嘉宾",true)],[new("视频","Video","https://example.com/video",null)],"高光","");await Data(await Write(f.Client,"/concerts/experiences/memories",memory));Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Write(f.Client,"/concerts/experiences/memories",memory with{Media=[new("非法链接","Video","javascript:alert(1)",null)]})).StatusCode);
  await using var other=await LifecycleFixture.Create();Assert.Empty((await Data(await other.Client.GetAsync("/api/concerts/trips"))).EnumerateArray());Assert.Empty((await Data(await other.Client.GetAsync("/api/concerts/experiences/memories"))).EnumerateArray());Assert.Equal(HttpStatusCode.NotFound,(await Write(other.Client,"/concerts/experiences/seats",seat)).StatusCode);Assert.Equal(count,await f.Db.Transactions.CountAsync());
 }
 [ProfileSqlFact] public async Task CollectionsBudgetsAndOverviewReadRealFactsWithoutCreatingMoneyOrValuation() {
  await using var f=await LifecycleFixture.Create();var pay=await f.Tx("Expense","100");var cost=new ConcertCost(Guid.NewGuid().ToString(),"Ticket",pay,null,"100","本人","本人");await Data(await Write(f.Client,"/concerts",Scene() with{Costs=[cost]}));
  var merchandise=await f.Tx("Expense","100");var item=new InterestItem(Guid.NewGuid().ToString(),"隔离专辑",null,"专辑","黑胶限定版",1,"100","0","0","0","100","Collection","Held",[]);var purchase=await Data(await Write(f.Client,"/concerts/interests/purchases",new InterestPurchase(new(2026,1,1),"CNY","渠道","商户","P1-ALBUM",merchandise,null,"Album","Purchased",[item],[],[],"")));
  var sale=await f.Tx("Income","50");var returned=await f.Tx("Expense","10");var initialCount=await f.Db.Transactions.CountAsync();var collection=new ConcertCollection("隔离专辑","CNY","黑胶","限定版","","黑色","P1-001","书柜","Sold",purchase.GetProperty("id").GetString(),item.Id,null,"100",sale,returned,[new(new(2026,1,1),"999999","个人记录，不是净资产")],"");
  var saved=await Data(await Write(f.Client,"/concerts/collections",collection));var list=await Data(await f.Client.GetAsync("/api/concerts/collections"));Assert.Equal("40.00",list[0].GetProperty("report").GetProperty("netSale").GetString());Assert.Equal("100.00",list[0].GetProperty("report").GetProperty("cost").GetString());
  Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Write(f.Client,"/concerts",Scene() with{Costs=[new(Guid.NewGuid().ToString(),"Other",returned,null,"10","本人","本人")]})).StatusCode);
  Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Write(f.Client,"/concerts/collections",collection with{PurchaseId=null,ItemId=null})).StatusCode);
  await Data(await Write(f.Client,"/concerts/planning-budgets",new ConcertPlanBudget("年度预算",2026,"CNY","Annual",null,"80",null,null,"40","")));var budgets=await Data(await f.Client.GetAsync("/api/concerts/planning-budgets"));Assert.Equal("100.00",budgets[0].GetProperty("report").GetProperty("actual").GetString());Assert.Equal("20.00",budgets[0].GetProperty("report").GetProperty("overspent").GetString());
  var overview=await Data(await f.Client.GetAsync("/api/concerts/overview?currency=CNY&year=2026"));Assert.Equal("100.00",overview.GetProperty("annual").GetProperty("totalCost").GetString());Assert.Equal("100.00",overview.GetProperty("interest").GetProperty("daily").GetProperty("net").GetString());Assert.Equal(initialCount,await f.Db.Transactions.CountAsync());
  await using var other=await LifecycleFixture.Create();Assert.Empty((await Data(await other.Client.GetAsync("/api/concerts/collections"))).EnumerateArray());Assert.Equal(HttpStatusCode.NotFound,(await other.Client.GetAsync("/api/concerts/p1-history/collections/"+saved.GetProperty("id").GetString())).StatusCode);
 }
}
